"""Contact sheet for substitute teachers."""

from typing import Iterable, List, Sequence

from rosterkit.models import Student
from rosterkit.errors import ProjectError

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Name, section and email rows lined up in columns, sorted by name."""
    ordered = sorted(students, key=lambda item: item.display_name)
    if not ordered:
        raise ProjectError("no students for the contact sheet")
    cells = [(one.display_name, one.section, _require_email(one)) for one in ordered]
    widths = [max(len(cell) for cell in column) for column in zip(*cells)]
    return [_format_row(row, widths) for row in cells]

def _require_email(student: Student) -> str:
    if not student.email:
        raise ProjectError(f"no email for {student.display_name}")
    return student.email

def _format_row(row: Sequence[str], widths: Sequence[int]) -> str:
    padded = (cell.ljust(width) for cell, width in zip(row, widths))
    return "  ".join(padded).rstrip()

