import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


class ContactRowTests(unittest.TestCase):
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_rows([
            Student("2", "Young", "Zed", "B2", "zed@example.org"),
            Student("1", "Adams", "Al", "A10", "al@example.org")
        ])
        self.assertEqual(rows, [
            "Adams, Al   A10  al@example.org",
            "Young, Zed  B2   zed@example.org"
        ])

    def test_missing_email_names_the_student(self):
        with self.assertRaises(ProjectError) as caught:
            contact_rows([Student("1", "Adams", "Al", "A10")])
        self.assertIn("Adams, Al", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
